struct pipe {
    char data[PIPESIZE];  // PIPESIZE = 512
    uint nread;           // number of bytes read
    uint nwrite;          // number of bytes written
    int readopen;         // read fd is still open
    int writeopen;        // write fd is still open
};

int pipealloc(struct file *f0, struct file *f1)
{
    struct pipe *pi = (struct pipe*)kalloc();
    if(pi == 0) return -1;  // 假设的内存分配失败检查
    pi->readopen = 1;
    pi->writeopen = 1;
    pi->nwrite = 0;
    pi->nread = 0;
    f0->type = FD_PIPE;
    f0->readable = 1;
    f0->writable = 0;
    f0->pipe = pi;
    f1->type = FD_PIPE;
    f1->readable = 0;
    f1->writable = 1;
    f1->pipe = pi;
    return 0;
}

/// 功能：为当前进程打开一个管道。
/// 参数：pipe 表示应用地址空间中的一个长度为 2 的 long 数组的起始地址，
///       内核需要按顺序将管道读端和写端的文件描述符写入到数组中。
/// 返回值：如果出现了错误则返回 -1，否则返回 0。
long sys_pipe(long fd[2]);

// 简化版 shell 执行 cat file.txt | wc -l 的逻辑
int pid1, pid2;
int fd[2];
pipe(fd);

if ((pid1 = fork()) == 0) {
    // 子进程1：执行 cat
    close(fd[0]);          // 关闭读端
    dup2(fd[1], STDOUT_FILENO);  // 重定向 stdout 到 pipe 写端
    close(fd[1]);          // 关闭原始写端（为什么？）
    execlp("cat", "cat", "file.txt", NULL);
}

if ((pid2 = fork()) == 0) {
    // 子进程2：执行 wc
    close(fd[1]);          // 关闭写端
    dup2(fd[0], STDIN_FILENO);   // 重定向 stdin 到 pipe 读端
    close(fd[0]);          // 关闭原始读端
    execlp("wc", "wc", "-l", NULL);
}

// 父进程 shell
close(fd[0]);
close(fd[1]);
waitpid(pid1, NULL, 0);
waitpid(pid2, NULL, 0);

